import pandas as pd

def clean(df):
    df = df.copy()
    # body_mass_g stored as text -> convert to numeric
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # drop invalid body mass (5050000 far exceeds allowed max 6500 g)
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    result = {}
    for species, group in df.groupby('species'):
        mean_mass = group['body_mass_g'].mean()
        if pd.notna(mean_mass):
            result[species] = mean_mass
    return result
